                        M_fuhai: {
                            audio: 'ext:琉璃亭/audio/skill:2',
                            enable: 'phaseUse',
                            usable: 1,
                            filter(event, player) {
                                return game.hasPlayer((current) => {
                                    return current.countCards('h');
                                });
                            },
                            filterTarget(card, player, target) {
                                return target.countCards('h');
                            },
                            selectTarget: -1,
                            multitarget: true,
                            multiline: true,
                            async content(event, trigger, player) {
                                const targets = event.targets.sortBySeat();
                                const next = player
                                    .chooseCardOL(targets, '请展示一张手牌', true)
                                    .set('ai', (card) => {
                                        return -get.value(card);
                                    })
                                    .set('aiCard', (target) => {
                                        const hs = target.getCards('h');
                                        return { bool: true, cards: [hs.randomGet()] };
                                    });
                                next._args.remove('glow_result');
                                const { result } = await next;
                                const cards = [];
                                const videoId = lib.status.videoId++;
                                for (var i = 0; i < targets.length; i++) {
                                    cards.push(result[i].cards[0]);
                                    game.log(targets[i], '展示了', result[i].cards[0]);
                                }
                                game.broadcastAll(
                                    (targets, cards, id, player) => {
                                        var dialog = ui.create.dialog(get.translation(player) + '发动了【浮海】', cards);
                                        dialog.videoId = id;
                                        const getName = (target) => {
                                            if (target._tempTranslate) return target._tempTranslate;
                                            var name = target.name;
                                            if (lib.translate[name + '_ab']) return lib.translate[name + '_ab'];
                                            return get.translation(name);
                                        };
                                        for (var i = 0; i < targets.length; i++) {
                                            dialog.buttons[i].querySelector('.info').innerHTML = getName(targets[i]) + '|' + get.strNumber(i.number);
                                        }
                                    },
                                    targets,
                                    cards,
                                    videoId,
                                    player
                                );
                                await game.asyncDelay(4);
                                game.broadcastAll('closeDialog', videoId);
                                let clock = -1,
                                    anticlock = -1;
                                for (let j = 0; j < 2; j++) {
                                    let increase = -Infinity,
                                        decrease = Infinity,
                                        count = 0;
                                    for (var i = 0; i < targets.length; i++) {
                                        const number = i.number;
                                        let flag = false;
                                        if (number >= increase) {
                                            increase = number;
                                            flag = true;
                                        } else increase = Infinity;
                                        if (number <= decrease) {
                                            decrease = number;
                                            flag = true;
                                        } else decrease = -Infinity;
                                        if (flag) count++;
                                        else break;
                                    }
                                    targets.reverse();
                                    cards.reverse();
                                    if (j == 0) anticlock = Math.max(1, count);
                                    else clock = Math.max(1, count);
                                }
                                const { index } = await player
                                    .chooseControl(`↖顺时针(${clock})`, `逆时针(${anticlock})↗`)
                                    .set('prompt', '请选择一个方向,摸对应数量的牌')
                                    .set('ai', () => get.event('choice'))
                                    .set('choice', clock > anticlock ? 0 : 2).forResult();
                                player.draw(index == 0 ? clock : anticlock);
                            },
                            ai: {
                                order: 8,
                                result: {
                                    player: 1,
                                },
                            },
                        },
